CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    email VARCHAR(100) UNIQUE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

const fs = require('fs');
const path = require('path');

/**
 * Migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const migrationsDir = path.join(__dirname, 'migrations');

// Check if migrations directory exists
if (!fs.existsSync(migrationsDir)) {
  console.error(`Migrations directory not found: ${migrationsDir}`);
  process.exit(1);
}

// Read all files from the migrations directory
let files;
try {
  files = fs.readdirSync(migrationsDir);
} catch (error) {
  console.error(`Error reading migrations directory: ${error.message}`);
  process.exit(1);
}

// Filter for SQL files only and sort them to ensure proper order
const sqlFiles = files
  .filter(file => file.endsWith('.sql'))
  .sort(); // Sort lexicographically to maintain order (001, 002, 003, etc.)

if (sqlFiles.length === 0) {
  console.log('No SQL migration files found in the migrations directory.');
  process.exit(0);
}

// Log each filename that would be applied, in order
console.log('Found migration files to apply in order:');
sqlFiles.forEach((file, index) => {
  console.log(`${index + 1}. ${file}`);
});

// Optional: Show the full paths that would be executed
console.log('\nFull paths:');
sqlFiles.forEach((file, index) => {
  const fullPath = path.join(migrationsDir, file);
  console.log(`${index + 1}. ${fullPath}`);
});

console.log(`\nTotal: ${sqlFiles.length} migration(s) would be applied.`);

