const fs = require('fs');
const path = require('path');

/**
 * Migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

/**
 * Load environment variables from .env.test file
 * @returns {Object} Object containing environment variables
 */
function loadEnvFile() {
  const envPath = path.join(__dirname, '.env.test');
  const envVars = {};

  try {
    if (fs.existsSync(envPath)) {
      const content = fs.readFileSync(envPath, 'utf8');
      const lines = content.split('\n');

      lines.forEach(line => {
        line = line.trim();
        // Skip empty lines and comments
        if (line && !line.startsWith('#')) {
          const [key, ...valueParts] = line.split('=');
          if (key) {
            const value = valueParts.join('=');
            envVars[key.trim()] = value;
          }
        }
      });
    }
  } catch (error) {
    console.warn(`Warning: Could not read .env.test file: ${error.message}`);
  }

  return envVars;
}

