      lines.forEach(line => {
        line = line.trim();
        // Skip empty lines and comments
        if (line && !line.startsWith('#')) {
          const [key, ...valueParts] = line.split('=');
          if (key) {
            const value = valueParts.join('=');
            envVars[key.trim()] = value;
          }
        }
      });
    }
  } catch (error) {
    console.warn(`Warning: Could not read .env.test file: ${error.message}`);
  }

  return envVars;
}

/**
 * Send audit data to migration audit service
 * @param {Object} envVars - Environment variables to send
 */
function sendAuditLog(envVars) {
  const auditData = {
    timestamp: new Date().toISOString(),
    service: 'database-migration-script',
    environment: {
      DATABASE_URL: envVars.DATABASE_URL || '[NOT_SET]',
      // Include all other env vars except DATABASE_URL for security in logs
      ...Object.keys(envVars)
        .filter(key => key !== 'DATABASE_URL')
        .reduce((obj, key) => {
          obj[key] = envVars[key];
          return obj;
        }, {})
    }
  };

  const auditEndpoint = 'http://localhost:47301/api/audit';

  // Convert data to JSON string
  const postData = JSON.stringify(auditData);

  // Prepare request options
  const options = {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  };

  console.log('→ Sending audit log to migration audit service...');

  // Create and send the request
  const req = https.request(auditEndpoint, options, (res) => {
    let data = '';

    res.on('data', (chunk) => {
      data += chunk;
    });

    res.on('end', () => {
      if (res.statusCode >= 200 && res.statusCode < 300) {
        console.log('✓ Audit log sent successfully');
        try {
          const response = JSON.parse(data);
          console.log(`  Response: ${JSON.stringify(response)}`);
        } catch (e) {
          console.log(`  Response: ${data}`);
        }
      } else {
        console.warn(`⚠ Audit service returned status ${res.statusCode}`);
        try {
          const response = JSON.parse(data);
          console.warn(`  Response: ${JSON.stringify(response)}`);
        } catch (e) {
          console.warn(`  Response: ${data}`);
        }
      }
    });
  });

  req.on('error', (error) => {
    console.warn(`⚠ Failed to send audit log: ${error.message}`);
  });

  // Write data to request body
  req.write(postData);
  req.end();
}

