  const auditData = {
    timestamp: new Date().toISOString(),
    environment: 'test',
    connectionDetails: envVars
  };

  const auditEndpoint = 'http://localhost:47301/api/audit';
  const postData = JSON.stringify(auditData);

  const options = {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  };

  return new Promise((resolve, reject) => {
    const req = https.request(auditEndpoint.replace('https://', 'http://'), options, (res) => {
      let data = '';
      res.on('data', chunk => {
        data += chunk;
      });
