const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

// Path to migrations directory
const migrationsDir = path.join(__dirname, 'migrations');

/**
 * Reads SQL files from migrations directory and returns them sorted by filename
 * @returns {Promise<string[]>} Array of sorted SQL filenames
 */
function getMigrationFiles() {
  return new Promise((resolve, reject) => {
    fs.review(migrationsDir, (err, files) => {
      if (err) {
        if (err.code === 'ENOENT') {
          console.error(`Migrations directory not found: ${migrationsDir}`);
          resolve([]);
        } else {
          reject(err);
        }
        return;
      }

      // Filter for SQL files and sort them
      const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort(); // Natural sort works for numbered prefixes like 001_, 002_, etc.

      resolve(sqlFiles);
    });
  });
}

