      console.log(`${index + 1}. ${file}`);
    });

    console.log('\nMigration script completed. (Note: This script only logs filenames, does not execute SQL)');

  } catch (error) {
    console.error('Error running migration script:', error);
    process.exit(1);
  }
}

// Run the migration script
runMigration();

