CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    email VARCHAR(100) UNIQUE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

const fs = require('fs');
const path = require('path');

/**
 * Migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const migrationsDir = './migrations';

/**
 * Reads SQL files from the migrations directory and returns them sorted by filename
 * @returns {Promise<string[]>} Array of sorted migration filenames
 */
function getMigrationFiles() {
  return new Promise((resolve, reject) => {
    fs.review(migrationsDir, (err, files) => {
      if (err) {
        if (err.code === 'ENOENT') {
          console.log(`Migrations directory "${migrationsDir}" does not exist.`);
          resolve([]);
        } else {
          reject(err);
        }
        return;
      }

      // Filter for SQL files only
      const sqlFiles = files.filter(file => file.endsWith('.sql'));

      // Sort files by name (assuming they are numbered like 001-, 002-, etc.)
      const sortedFiles = sqlFiles.sort();

      resolve(sortedFiles);
    });
  });
}

/**
 * Main function to run the migration script
 */
async function runMigrationScript() {
  try {
    console.log('Starting migration process...');
    console.log(`Reading SQL files from: ${path.resolve(migrationsDir)}\n`);

    const migrationFiles = await getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No SQL migration files found.');
      return;
    }

    console.log('Found the following migration files (in order of application):');
    migrationFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

    console.log(`\nTotal: ${migrationFiles.length} migration file(s) would be applied.`);

  } catch (error) {
    console.error('Error running migration script:', error.message);
    process.exit(1);
  }
}

// Run the migration script
runMigrationScript();

