/**
 * Sends environment data to the audit service
 * @param {Object} envData - Object containing environment variables
 * @returns {Promise<void>}
 */
async function sendToAuditService(envData) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(envData);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': data.length
      }
    };

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Audit log sent successfully');
          resolve();
        } else {
          console.warn(`Audit service responded with status: ${res.statusCode}`);
          resolve(); // Don't fail migration for audit issues
        }
      });
    });

    req.on('error', (error) => {
      console.warn(`Failed to send audit log: ${error.message}`);
      resolve(); // Don't fail migration for audit issues
    });

    req.write(data);
    req.end();
  });
}

