          resolve([]);
          return;
        }
        reject(err);
        return;
      }

      // Filter for SQL files only and sort them
      const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort(); // Sort alphabetically (001, 002, 003, etc.)

      resolve(sqlFiles);
    });
  });
}

/**
 * Validates that migration files follow a naming convention (optional)
 * @param {string[]} files - Array of migration filenames
 * @returns {Object} Validation result with warnings if any
 */
function validateMigrationFiles(files) {
  const warnings = [];

  files.forEach((file, index) => {
    // Check if file follows the common pattern: XXX-description.sql
    if (!/^\d{3}-/.test(file)) {
      warnings.push(`File "${file}" doesn't follow the recommended naming convention (XXX-description.sql)`);
    }

    // Check for duplicate numbers (basic check)
    const num = file.match(/^(\d{3})/);
    if (num) {
      const duplicate = files.some(f => f !== file && f.startsWith(num[1]));
      if (duplicate) {
        warnings.push(`Duplicate migration number found in "${file}"`);
      }
    }
  });

  return { warnings };
}

/**
 * Main function to run the migration script
 */
async function runMigration() {
  try {
    console.log('🔍 Starting migration process...');
    console.log(`📁 Looking for migrations in: ${migrationsDir}`);

