function getMigrationFiles() {
  try {
    // Read all files in the migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort(); // This will sort lexicographically, which works for numbered prefixes

    return sqlFiles;
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.error(`Migrations directory not found: ${migrationsDir}`);
      return [];
    }
    throw error;
  }
}

// Main function to log migration files
function runMigrations() {
  console.log('Starting database migration process...');

  // Load environment variables first
  loadEnv();

  // Resolve and log database connection
  const databaseUrl = process.env.DATABASE_URL;
  if (databaseUrl) {
    // Parse just the host/database part for security (don't log credentials)
    try {
      const urlObj = new URL(databaseUrl);
      console.log(`✓ Connected to database: ${urlObj.hostname}:${urlObj.port}${urlObj.pathname}`);
    } catch (e) {
      console.log('✓ Database connection resolved from DATABASE_URL');
    }
  } else {
    console.log('! DATABASE_URL not found in environment');
  }

  console.log(`Looking for SQL migration files in: ${migrationsDir}\n`);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  // Log each filename it would apply, in order
  migrationFiles.forEach((file, index) => {
    console.log(`${index + 1}. Would apply: ${file}`);
  });

  console.log('\nMigration process completed.');
}

// Run the migration script
runMigrations();

module.exports = { getMigrationFiles, runMigrations };

